423	(function(){
424	  const eventDate = new Date('2026-03-17T14:00:00+08:00').getTime();
425	  const ids = {
426	    days: document.getElementById('days'),
427	    hours: document.getElementById('hours'),
428	    minutes: document.getElementById('minutes'),
429	    seconds: document.getElementById('seconds'),
430	    liveCount: document.getElementById('live-count'),
431	    remainingCount: document.getElementById('remaining-count')
432	  };
433	
434	  function pad(n){ return String(n).padStart(2,'0'); }
435	
436	  function updateCountdown(){
437	    const now = Date.now();
438	    const diff = eventDate - now;
439	    if(diff <= 0){
440	      ids.days.textContent = '00';
441	      ids.hours.textContent = '00';
442	      ids.minutes.textContent = '00';
443	      ids.seconds.textContent = '00';
444	      return;
445	    }
446	    const days = Math.floor(diff / (1000*60*60*24));
447	    const hours = Math.floor((diff / (1000*60*60)) % 24);
448	    const minutes = Math.floor((diff / (1000*60)) % 60);
449	    const seconds = Math.floor((diff / 1000) % 60);
450	    ids.days.textContent = pad(days);
451	    ids.hours.textContent = pad(hours);
452	    ids.minutes.textContent = pad(minutes);
453	    ids.seconds.textContent = pad(seconds);
454	  }
455	
456	  function updateLiveCount(){
457	    const startCount = 41;            // 目前起始報名人數
458	    const maxSeats = 60;              // 總席次
459	    const startDate = new Date('2026-03-15T00:00:00+08:00').getTime(); // 修改這裡：開始累積的基準日（今天凌晨）
460	
461	    const now = Date.now();
462	    const hoursPassed = Math.floor((now - startDate) / (1000 * 60 * 60));
463	
464	    // 每3小時 +1 人
465	    const increments = Math.floor(hoursPassed / 3);
466	
467	    let current = startCount + increments;
468	
469	    if(current > maxSeats){
470	      current = maxSeats;
471	    }
472	
473	    ids.liveCount.textContent = current;
474	    ids.remainingCount.textContent = Math.max(0, maxSeats - current);
475	  }
476	
477	  updateCountdown();
478	  updateLiveCount();
479	  setInterval(updateCountdown, 1000);
480	  setInterval(updateLiveCount, 60000);  // 每分鐘檢查一次人數變化
481	})();
482	</script>
