}
.signup-option .btn{
  width:100%;
  margin-top:auto;
}

.speaker-grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:18px;
}
.speaker-card{
  background:#fff;
  border:1px solid rgba(18,34,56,.08);
  border-radius:22px;
  padding:20px;
  box-shadow:var(--shadow);
  display:grid;
  grid-template-columns:132px 1fr;
  gap:18px;
  align-items:start;
  transition:.2s ease;
}
.speaker-card:hover{
  transform:translateY(-3px);
  box-shadow:0 18px 36px rgba(18,34,56,.12);
}
.speaker-photo-link{display:block}
.speaker-photo{
  width:132px;
  aspect-ratio:1 / 1.2;
  border-radius:18px;
  background:#f4fbfb;
  border:1px solid rgba(18,34,56,.08);
  display:flex;
  align-items:center;
  justify-content:center;
  overflow:hidden;
  box-shadow:0 10px 24px rgba(18,34,56,.08);
}
.speaker-photo img{
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:center top;
}
.speaker-content .org{
  display:inline-flex;
  align-items:center;
  padding:6px 10px;
  border-radius:999px;
  background:rgba(29,141,149,.08);
  border:1px solid rgba(29,141,149,.14);
  color:var(--teal-dark);
  font-size:13px;
  line-height:1.4;
  font-weight:800;
  margin-bottom:10px;
}
.speaker-content .name{
  color:var(--navy);
  font-size:28px;
  font-weight:900;
  line-height:1.1;
  margin-bottom:4px;
}
.speaker-content .title{
  color:var(--teal-dark);
  font-size:16px;
  font-weight:800;
  margin-bottom:10px;
}
.speaker-content .topic{
  background:linear-gradient(135deg, rgba(29,141,149,.08), rgba(98,195,198,.12));
  border-radius:14px;
  padding:12px 14px;
  color:var(--navy);
  font-weight:800;
  line-height:1.55;
  margin-bottom:12px;
}
.speaker-actions{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
}
.btn-mini{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:38px;
  padding:8px 14px;
  border-radius:999px;
  font-size:13px;
  font-weight:900;
  background:linear-gradient(135deg, var(--teal-deep), var(--teal));
  color:#fff;
  border:none;
  box-shadow:0 8px 18px rgba(29,141,149,.22);
}

.bio-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:18px;
}
.bio-card{
  padding:24px;
  scroll-margin-top:100px;
}
.bio-card h3{
  font-size:22px;
  color:var(--navy);
  font-weight:900;
  margin-bottom:8px;
}
.bio-card p{
  color:var(--muted);
  font-size:15px;
  line-height:1.85;

